import yaml

def service_port(config_text: str) -> int:
    data = yaml.load(config_text, Loader=yaml.SafeLoader)
    if not isinstance(data, dict):
        raise ValueError("Top level YAML document is not a mapping")
    if 'service' not in data or not isinstance(data['service'], dict):
        raise KeyError("Missing 'service' mapping")
    if 'port' not in data['service']:
        raise KeyError("Missing 'service.port' key")
    return int(data['service']['port'])
